import { type EmailOtpType } from "@supabase/supabase-js";
import { NextResponse } from "next/server";

import { createClient } from "@/lib/supabase/server";

/**
 * Merchant email-verification callback.
 *
 * The combined signup (backend POST /v1/onboarding/signup) creates the
 * Supabase Auth user and emails a verification link generated by
 * `auth.admin.generate_link({type: "signup", redirect_to: <this route>})`;
 * `resendVerificationAction` (`auth.resend`) produces the same kind of
 * link. Once clicked, the link lands back here with either:
 *
 *   - `?code=...`                     (exchange it for a session)
 *   - `?token_hash=...&type=signup`   (verify the OTP directly)
 *
 * On success we establish the session cookie and forward the merchant on
 * (`?next=`, default `/dashboard/overview` — the pending-review page). On
 * any failure — an expired or already-consumed link, or a link opened in
 * a browser that never held the PKCE verifier — we send them to
 * /dashboard/login with a plain-language notice, never a stack trace and
 * never a bare 400.
 *
 * A hash-fragment callback (`#access_token=...`) can't be handled here
 * because fragments are never sent to the server; this flow never
 * produces one, so there is nothing to catch for it.
 */

const SAFE_NEXT = /^\/[a-zA-Z0-9/_-]*$/;

function loginRedirect(origin: string, notice: string) {
  const url = new URL("/dashboard/login", origin);
  url.searchParams.set("notice", notice);
  return NextResponse.redirect(url);
}

export async function GET(request: Request) {
  const { searchParams, origin } = new URL(request.url);

  const rawNext = searchParams.get("next") ?? "/onboarding";
  const next = SAFE_NEXT.test(rawNext) ? rawNext : "/onboarding";

  const code = searchParams.get("code");
  const tokenHash = searchParams.get("token_hash");
  const type = searchParams.get("type") as EmailOtpType | null;
  const errorDescription = searchParams.get("error_description");

  if (errorDescription) {
    return loginRedirect(
      origin,
      "Your verification link is invalid or has expired. Sign in and we'll send you a new one.",
    );
  }

  const supabase = await createClient();

  if (code) {
    const { error } = await supabase.auth.exchangeCodeForSession(code);
    if (!error) {
      return NextResponse.redirect(new URL(next, origin));
    }
  } else if (tokenHash && type) {
    const { error } = await supabase.auth.verifyOtp({ type, token_hash: tokenHash });
    if (!error) {
      return NextResponse.redirect(new URL(next, origin));
    }
  }

  // Either there was no usable token, or redeeming it failed.
  //
  // This used to say "Your email is verified. Sign in to continue",
  // written for the benign case of a link clicked twice after it was
  // already spent. When redeeming genuinely fails — an expired link, most
  // often — that sentence is false, and it closes a loop with no way out:
  // the merchant is told they are verified, signs in, and is told their
  // email still needs verifying. Two screens contradicting each other and
  // nothing to do about either.
  //
  // We cannot tell the two cases apart from here, so the wording has to
  // be true in both and carry the next step either way. Signing in is
  // what resolves it for someone already verified; "Send it again" is on
  // that same page for someone who is not.
  return loginRedirect(
    origin,
    "That link didn't work — it may have expired or already been used. Try signing in; " +
      "if your email still needs verifying, use “Send it again” below.",
  );
}
